def main():
    target=ROOT/'content'/'408'
    target.mkdir(parents=True, exist_ok=True)
    catalog=[]
    for course in SUBJECTS:
        cid=course['id']
        chapters=course.pop('chapters')
        lines=[f"# {course['title']} · 408 原创导学手册", '', '版本：1.0 | 项目：学思同行 | 许可：CC BY 4.0（本项目原创内容）', '', '这是围绕常见专业课知识点编写的补充导学资料，非指定商业教材、非官方考试大纲。它提供概念、计算假设、典型易错点与小例子，不替代完整教材；具体课程要求请核对教师资料。所有页码以实际上传PDF为准，本Markdown按章节定位。', '']
        concepts=[]; edges=[]
        for i,(label,text) in enumerate(chapters,1):
            lines.extend([f'## {i:02d} {label}', '', text, '', f'### 自查：{label}', '', '尝试用自己的话解释上述概念，先写清适用条件，再选择算法或代入公式；如果更改假设，检查结论是否仍成立。遇到教材不同记号时，先对齐定义。', ''])
            concepts.append(dict(id=f'{cid}-{i}',label=label,chapter=f'第{i}章'))
            if i>1: edges.append(dict(source=f'{cid}-{i-1}',target=f'{cid}-{i}',relation='学习关联'))
        # Curriculum associations are hand-authored, not claims of formal prerequisite proofs.
        extra = {'data-structures':[(1,7),(3,8),(5,6),(8,9),(8,10),(1,12)],'computer-organization':[(2,3),(4,5),(5,6),(7,8),(8,12),(9,10)],'operating-systems':[(1,2),(3,4),(4,5),(6,7),(7,8),(8,9),(10,11)],'computer-networks':[(1,2),(3,4),(5,7),(6,7),(8,9),(10,11)]}[cid]
        edges.extend(dict(source=f'{cid}-{a}',target=f'{cid}-{b}',relation='知识关联') for a,b in extra)
        path=target/f'{cid}.md'; path.write_text('\n'.join(lines),encoding='utf-8')
        questions=[]
        for i,(stem,options,answer,concept,explanation) in enumerate(BANKS[cid],1):
            questions.append(dict(id=f'{cid}-q{i}',stem=stem,options=[dict(key=chr(65+k),text=t) for k,t in enumerate(options)],answer=chr(65+answer),explanation=explanation,concept=concept,difficulty='基础' if i<=4 else '进阶' if i<=8 else '挑战'))
        course.update(documents=[dict(path=str(path.relative_to(ROOT)).replace('\\','/'),title=f"{course['title']} · 408 原创导学手册",license='CC BY 4.0 · 项目原创',source_type='original',source_url='')],concepts=concepts,edges=edges,questions=questions)
        manifest=ROOT/'content/open-textbooks/manifest.json'
        if manifest.exists():
            for document in json.loads(manifest.read_text(encoding='utf-8')):
                if document['course_id']==cid:
                    course['documents'].append({k:v for k,v in document.items() if k!='course_id'})
        catalog.append(course)
    (ROOT/'content'/'catalog.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'courses':len(catalog),'sections':sum(len(c['concepts']) for c in catalog),'questions':sum(len(c['questions']) for c in catalog)},ensure_ascii=False))

if __name__=='__main__': main()
